import React from "react";

const InfoSection = () => {
  const cards = [
    {
      title: "What is Churn?",
      text: "Churn prediction identifies customers likely to leave a service based on past behavior."
    },
    {
      title: "Dataset Used",
      text: "Includes demographics, tenure, monthly charges, contract type, payment method, etc."
    },
    {
      title: "Algorithms",
      text: "Logistic Regression, Random Forest, XGBoost, SVM, Neural Networks."
    },
    {
      title: "Benefits",
      text: "Reduce customer loss, increase retention, boost profitability, business insights."
    },
    {
      title: "Use Cases",
      text: "Telecom, SaaS, OTT, Banking, Subscription-based applications."
    }
  ];

  return (
    <div style={{ marginTop: "30px" }}>
      <h2 style={{ fontSize: "28px", color: "white", marginBottom: "20px" }}>
        Churn Prediction Overview
      </h2>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(250px, 1fr))",
          gap: "20px"
        }}
      >
        {cards.map((c, i) => (
          <div key={i} className="info-card">
            <h3 style={{ marginBottom: "10px" }}>{c.title}</h3>
            <p>{c.text}</p>
          </div>
        ))}
      </div>
    </div>
  );
};

export default InfoSection;
